def prepare():
    import hashlib, importlib, importlib.util, sys
    from pathlib import Path
    package='glm_reconstruction_v985_helpers'
    root=Path('/srv/ai/artifacts/glm-prefill-weight-reuse-20261007/build-v985-offsets/glm_reconstruction_v985_helpers')
    if package not in sys.modules:
        spec=importlib.util.spec_from_file_location(package,root/'__init__.py',submodule_search_locations=[str(root)])
        module=importlib.util.module_from_spec(spec)
        sys.modules[package]=module
        spec.loader.exec_module(module)
    if Path(sys.modules[package].__file__).resolve() != (root/'__init__.py').resolve():
        raise ValueError('fused helper package belongs to another build')
    for name, expected in {'reconstruction_native.py': '9bf814f721c063009c3e211841a55f7940c849c99d018d0822227f1cc3f5752c', 'reconstruction_probe.py': '53671a4e566771d23f945d55037e24cc7120df8a7d21672802b5a5e2724f3d83', 'glm_int4.py': 'be71985a4fd66c3f99d950abb5da4f8383ad607c421c8b3bfbe1ec3564e0a843', 'glm_fused_moe.py': 'cbd4ad60564260f3ee52b5248039a173e5cc585a31335b9035e13b93af6a00d2', 'fused_moe_probe.py': '30a186fcf10a3c28652e77f16cf0520f9b3c03a19eec72cb6761c90f1b61eb97', 'fused_weight_layout.py': 'dde6829b0be8238d91ee7bdd89246874bb13ab4379e29cfc057faaebd98ca6f0', 'fused_offset_tables.py': '6039185853aa42c9630a9b991048021e9e0962dc7c5baded05912bcc3b0513ea', 'expert_reconstruction.py': '2d3bfc73b1736f2abe605b43c0e0d81f483afa88c5c79c050df5faa630cea1a4', '__init__.py': '6c6ec57de9f82ef42d82760f144a4571cb16b3cd6de33aaa7aa9fd65e8ab1fa1'}.items():
        if hashlib.sha256((root/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('fused helper changed: '+name)
    from glm_reconstruction_v985_helpers.glm_fused_moe import NativeFusedMoE
    build=Path('/srv/ai/artifacts/glm-prefill-weight-reuse-20261007/build-v985-offsets')
    resources={'fused_int4a'+str(bits): NativeFusedMoE(build,namespace='glm_reconstruction_v985',activation_bits=bits,
                                                     prepared_weight_layout=True,fp16_route_workspace=True)
               for bits in (8,4)}
    if True:
        import torch
        from glm_reconstruction_v985_helpers.fused_weight_layout import PreparedWeightLayout
        report=Path('/srv/ai/artifacts/glm-prefill-weight-reuse-20261007/build-v985-offsets')/('weight-layout-rank'+str(torch.distributed.get_rank())+'.json')
        resources['_weight_layout']=PreparedWeightLayout(torch.npu.synchronize,torch.distributed.get_world_size(),
                                                         report_path=report)
    return resources

def validate(resources):
    from glm_reconstruction_v985_helpers.fused_moe_probe import gate_case
    records=[gate_case(resources['fused_int4a'+str(activation)],bits,tokens=tokens)
             for activation in (8,4) for bits in (2,3,4) for tokens in (2, 17)]

    import gc as garbage_collector
    import torch
    audit=[]
    def collect_tensors(value):
        if isinstance(value,torch.Tensor):return [value]
        if isinstance(value,(list,tuple)):return [t for child in value for t in collect_tensors(child)]
        return []
    for obj in garbage_collector.get_objects():
        if type(obj).__name__ != 'NPUWorker310':continue
        data=getattr(obj,'__dict__',None)
        if type(data) is dict and 'model_runner' in data:
            runner=data['model_runner']
            if runner is not None and 'kv_caches' in vars(runner):
                for index,bank in enumerate(vars(runner)['kv_caches']):
                    tensors=collect_tensors(bank)
                    if tensors:audit.append(dict(owner=type(obj).__name__,index=index,shapes=[list(t.shape) for t in tensors],dtypes=[str(t.dtype) for t in tensors],pointers=[t.data_ptr() for t in tensors]))
    for native in resources.values():
        if hasattr(native,'configs'):native.configs.clear()
        if hasattr(native,'scratch'):native.scratch.clear()
    torch.npu.synchronize();garbage_collector.collect();torch.npu.empty_cache()
    return {'passed':True,'cache_storage_audit':audit,'cases':len(records),'native_fused_stages':2,
             'input_quantization_passes_per_token':1,
             'fp16_intermediate_gm_bytes':max(r['fp16_intermediate_gm_bytes'] for r in records),
             'model_quality':'not_evaluated'}
